using System.IO.Compression;
using CssLauncher.Game;
using CssLauncher.Core;
using Xunit;

namespace CssLauncher.Tests;

public class CoreTests
{
    [Fact] public void ParsesLibraryFolders() { var result = new LibraryFoldersVdfParser().Parse("\"path\" \"C:\\\\SteamLibrary\"\n\"path\" \"D:\\\\Games\""); Assert.Equal(2, result.Count); Assert.Contains("C:\\SteamLibrary", result); }
    [Fact] public void ParsesAppManifestBuildId() { Assert.Equal("11003710", new AppManifestParser().ParseBuildId("\"appid\" \"240\"\n\"buildid\" \"11003710\"")); }
    [Fact] public void ResolvesSteamAppManifestFromGameRoot() { var root = Path.Combine(Path.GetTempPath(), "Steam", "steamapps", "common", "Counter-Strike Source"); Assert.Equal(Path.GetFullPath(Path.Combine(root, "..", "..", "appmanifest_240.acf")), SteamPathHelper.GetAppManifestPath(root)); }
    [Fact] public void ParsesSteamInfClientVersion() { var values = new SteamInfParser().Parse("PatchVersion=11003710\nClientVersion=11003710\nServerVersion=11003710"); Assert.Equal("11003710", values["ClientVersion"]); Assert.Equal("11003710", new SteamInfParser().ParseClientVersion("PatchVersion=11003710\nClientVersion=11003710")); }
    [Fact] public void DetectsCstrikeBeforeHl2() { var root = Path.Combine(Path.GetTempPath(), "CssExe-" + Guid.NewGuid()); Directory.CreateDirectory(root); File.WriteAllText(Path.Combine(root, "cstrike.exe"), ""); File.WriteAllText(Path.Combine(root, "hl2.exe"), ""); var result = GameExecutableDetector.Detect(root); Assert.Equal(Path.Combine(root, "cstrike.exe"), result.PreferredPath); Assert.Equal(2, result.FoundPaths.Count); Directory.Delete(root, true); }
    [Fact] public void DetectsNoExecutable() { var root = Path.Combine(Path.GetTempPath(), "CssExe-" + Guid.NewGuid()); Directory.CreateDirectory(root); var result = GameExecutableDetector.Detect(root); Assert.Null(result.PreferredPath); Assert.Empty(result.FoundPaths); Directory.Delete(root, true); }
    [Fact] public void RejectsUnsafeManifestPath() { Assert.False(VersionChecker.IsSafeRelativePath("../secret")); Assert.False(VersionChecker.IsSafeRelativePath("C:\\secret")); Assert.False(VersionChecker.IsSafeRelativePath("/absolute")); Assert.False(VersionChecker.IsSafeRelativePath("foo:bar")); Assert.True(VersionChecker.IsSafeRelativePath("cstrike/gameinfo.txt")); }
    [Fact] public void SplitsExtraArgumentsWithQuotes() { var args = GameLauncher.SplitExtra("-foo \"hello world\" -bar").ToArray(); Assert.Equal(new[] { "-foo", "hello world", "-bar" }, args); }
    [Fact] public async Task KnownClientVersionIsConfirmed() { var library = Path.Combine(Path.GetTempPath(), "CssLibrary-" + Guid.NewGuid()); var root = Path.Combine(library, "steamapps", "common", "Counter-Strike Source"); Directory.CreateDirectory(Path.Combine(root, "cstrike")); File.WriteAllText(Path.Combine(root, "cstrike.exe"), "game"); File.WriteAllText(Path.Combine(root, "cstrike", "gameinfo.txt"), "info"); File.WriteAllText(Path.Combine(root, "cstrike", "steam.inf"), "ClientVersion=11003710\nPatchVersion=11003710"); await File.WriteAllTextAsync(Path.Combine(library, "steamapps", "appmanifest_240.acf"), "\"buildid\" \"25338318\""); var manifest = Path.Combine(library, "manifest.json"); await File.WriteAllTextAsync(manifest, "{\"schemaVersion\":2,\"game\":\"CS:S\",\"version\":\"11003710\",\"knownVersions\":[11003710],\"knownBuilds\":[25338318],\"enableSha256Checks\":false}"); var result = await new VersionChecker(manifest).CheckAsync(root); Assert.Equal(VersionStatus.Confirmed, result.Status); Assert.Equal("11003710", result.ClientVersion); Assert.Equal("25338318", result.BuildId); Directory.Delete(library, true); }
    [Fact] public async Task UnknownClientVersionReturnsWarningStatus() { var library = Path.Combine(Path.GetTempPath(), "CssLibrary-" + Guid.NewGuid()); var root = Path.Combine(library, "steamapps", "common", "Counter-Strike Source"); Directory.CreateDirectory(Path.Combine(root, "cstrike")); File.WriteAllText(Path.Combine(root, "hl2.exe"), "game"); File.WriteAllText(Path.Combine(root, "cstrike", "gameinfo.txt"), "info"); File.WriteAllText(Path.Combine(root, "cstrike", "steam.inf"), "ClientVersion=99999999"); await File.WriteAllTextAsync(Path.Combine(library, "steamapps", "appmanifest_240.acf"), "\"buildid\" \"25338318\""); var manifest = Path.Combine(library, "manifest.json"); await File.WriteAllTextAsync(manifest, "{\"schemaVersion\":2,\"game\":\"CS:S\",\"version\":\"11003710\",\"knownVersions\":[11003710],\"knownBuilds\":[25338318],\"enableSha256Checks\":false}"); var result = await new VersionChecker(manifest).CheckAsync(root); Assert.Equal(VersionStatus.UnknownBuild, result.Status); Assert.Contains("ClientVersion 99999999", result.Message); Directory.Delete(library, true); }
    [Fact] public async Task EmptyVersionListReturnsManifestEmpty() { var root = Path.Combine(Path.GetTempPath(), "CssBuild-" + Guid.NewGuid()); Directory.CreateDirectory(Path.Combine(root, "cstrike")); File.WriteAllText(Path.Combine(root, "hl2.exe"), "game"); File.WriteAllText(Path.Combine(root, "cstrike", "gameinfo.txt"), "info"); var manifest = Path.Combine(root, "manifest.json"); await File.WriteAllTextAsync(manifest, "{\"schemaVersion\":2,\"game\":\"CS:S\",\"version\":\"current\",\"knownVersions\":[]}"); var result = await new VersionChecker(manifest).CheckAsync(root); Assert.Equal(VersionStatus.ManifestEmpty, result.Status); Directory.Delete(root, true); }
    [Fact] public async Task ProfileUsesUnicodeAndSpacesWithoutTouchingGame() { var root = Path.Combine(Path.GetTempPath(), "Игра с пробелом-" + Guid.NewGuid()); var app = Path.Combine(Path.GetTempPath(), "CssLauncherTest-" + Guid.NewGuid()); Directory.CreateDirectory(root); Directory.CreateDirectory(app); var template = Path.Combine(app, "template.txt"); await File.WriteAllTextAsync(template, "root={GAME_ROOT}"); var profile = await new ProfileService(template, app).CreateOrUpdateAsync(root); var text = await File.ReadAllTextAsync(Path.Combine(profile, "gameinfo.txt")); Assert.Contains("Игра с пробелом-", text); Assert.True(Directory.Exists(Path.Combine(profile, "custom"))); Directory.Delete(root, true); Directory.Delete(app, true); }
    [Fact] public async Task DiagnosticArchiveIncludesSteamManifestFromLibraryRoot() { var library = Path.Combine(Path.GetTempPath(), "CssDiagLibrary-" + Guid.NewGuid()); var game = Path.Combine(library, "steamapps", "common", "Counter-Strike Source"); var app = Path.Combine(Path.GetTempPath(), "CssDiagApp-" + Guid.NewGuid()); Directory.CreateDirectory(Path.Combine(game, "cstrike")); Directory.CreateDirectory(Path.Combine(library, "steamapps")); Directory.CreateDirectory(app); await File.WriteAllTextAsync(Path.Combine(game, "cstrike", "steam.inf"), "ClientVersion=11003710"); await File.WriteAllTextAsync(Path.Combine(library, "steamapps", "appmanifest_240.acf"), "\"buildid\" \"25338318\""); var result = await new DiagnosticArchiveService(app).CreateAsync(game); using (var zip = ZipFile.OpenRead(result.ArchivePath)) { Assert.Contains(zip.Entries, x => x.FullName == "game/cstrike/steam.inf"); Assert.Contains(zip.Entries, x => x.FullName == "external/appmanifest_240.acf"); } Directory.Delete(library, true); Directory.Delete(app, true); }
}
